/deep/.ivu-tabs-bar{
    margin-bottom: 30px!important;
}

.ivu-btn[data-v-7bfea95a]:only-child{
    margin-left: 0!important;
}

.fixed-card {
    position: fixed;
    right: 0;
    bottom: 0;
    left: 200px;
    z-index: 99;
    box-shadow: 0 -1px 2px rgb(240, 240, 240);

    /deep/ .ivu-card-body {
        padding: 15px 16px 14px;
    }

    .ivu-form-item {
        margin-bottom: 12px!important;
    }

    /deep/ .ivu-form-item-content {
        margin-right: 124px;
        text-align: center;
    }

    .ivu-btn {
        height: 36px;
        padding: 0 20px;
    }
}

.tips{
    color: #999999;
    margin-top: 5px;
}

.w_input{
    width:460px;
}

.ivu-tabs {
    overflow: visible;
}

.upload-list {
    display: inline-block;
    margin: 0 0 -10px 0;

    .upload-item {
        position: relative;
        display: inline-block;
        width: 64px;
        height: 64px;
        border: 1px dashed #DDDDDD;
        border-radius: 4px;
        margin: 0 15px 10px 0;
        &.on{
          width: 100%;
          height: 40px;
        }
    }

    img {
        width: 100%;
        height: 40px;
        border-radius: 4px;
        vertical-align: middle;
    }

    .ivu-btn {
        position: absolute;
        top: 0;
        right: 0;
        width: 20px;
        height: 20px;
        margin: -10px -10px 0 0;
    }
}

.upload-select {
    width: 64px;
    height: 64px;
    font-size: 35px !important;
    background: #f5f5f5;
    color: #ccc;
}

.select-tag {
    position: relative;
    min-height: 32px;
    padding: 0 24px 0 4px;
    border: 1px solid #dcdee2;
    border-radius: 4px;
    line-height: normal;
    user-select: none;
    cursor: pointer;

    &:hover {
        border-color: #57a3f3;
    }

    .ivu-icon {
        position: absolute;
        top: 50%;
        right: 8px;
        line-height: 1;
        transform: translateY(-50%);
        font-size: 14px;
        color: #808695;
        transition: all 0.2s ease-in-out;
    }

    .ivu-tag {
        position: relative;
        max-width: 99%;
        height: 24px;
        margin: 3px 4px 3px 0;
        line-height: 22px;
    }

    .placeholder {
        display: block;
        height: 30px;
        line-height: 30px;
        color: #c5c8ce;
        font-size: 14px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        padding-left: 4px;
        padding-right: 22px;
    }
}

.ivu-radio-wrapper {
    margin-right: 30px;
}

.ivu-form-item+.ivu-row {
    padding: 0 20px;
}

.fixed-card .ivu-btn {
    +.ivu-btn {
        margin-left: 14px;
    }

    &:only-child {
        margin-left: 14px;
    }
}

.ivu-card {
    margin-top: 14px;

    /deep/.ivu-tabs-tab {
        padding: 20px 16px;
        line-height: 1;
    }
}
